import java.util.Locale;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int amount = Integer.parseInt(sc.next());
        if (amount < 0) {
            System.out.println("Invalid Amount");
        } else {
            int discount;
            if (amount >= 5000) {
                discount = 20;
            } else if (amount >= 2000) {
                discount = 10;
            } else if (amount >= 1000) {
                discount = 5;
            } else {
                discount = 0;
            }
            double finalAmount = amount * (100 - discount) / 100.0;
            System.out.println(discount);
            System.out.println(String.format(Locale.US, "%.2f", finalAmount));
        }
    }
}

